function demo() {$("#content").val("192.168.10.1");}function ip2long() {var ip = $("#content").val();ip = ip.split(".");num = Number(ip[0]) * 256 * 256 * 256 + Number(ip[1]) * 256 * 256 + Number(ip[2]) * 256 + Number(ip[3]);num = num >>> 0;document.getElementById('result').value = num;}function long2ip() {var num = $("#content").val();var tt = new Array();tt[0] = (num >>> 24) >>> 0;tt[1] = ((num << 8) >>> 24) >>> 0;tt[2] = (num << 16) >>> 24;tt[3] = (num << 24) >>> 24;str = String(tt[0]) + "." + String(tt[1]) + "." + String(tt[2]) + "." + String(tt[3]);document.getElementById('result').value = str;}function Empty() {$("#content").val("");$("#result").val("");$("#content").select();}
